#include <algorithm>
#include <array>
#include <iostream>
#include <numeric>
#include <set>
#include <stdexcept>
#include <vector>
using namespace std;using R=vector<int>;using V=array<long long,3>;using ll=long long;
void need(bool b,const char*s){if(!b)throw runtime_error(s);}ll factorial(int n){ll a=1;while(n)a*=n--;return a;}
R tournament(int n,int mask){R r(n);int k=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++,k++)r[mask>>k&1?i:j]|=1<<(mask>>k&1?j:i);return r;}
R trans(int n){R r(n);for(int i=0;i<n;i++)for(int j=i+1;j<n;j++)r[i]|=1<<j;return r;}
R converse(R r){int F=(1<<r.size())-1;for(int i=0;i<(int)r.size();i++)r[i]=F^r[i]^(1<<i);return r;}
V cover(R const&r){int n=r.size();vector<int>p(n);iota(p.begin(),p.end(),0);V a{};do{for(int cuts=0;cuts<(1<<(n-1));cuts++){int k=__builtin_popcount((unsigned)cuts);if(k>2)continue;bool ok=true;for(int i=0;i<n-1;i++)if(!(cuts>>i&1)&&!(r[p[i]]>>p[i+1]&1)){ok=false;break;}if(ok)a[k]++;}}while(next_permutation(p.begin(),p.end()));for(int i=0;i<3;i++){need(a[i]%factorial(i+1)==0,"ordered cover factorial");a[i]/=factorial(i+1);}return a;}
R cyclic(R const&t,R const&u){vector<pair<int,int>>ids;for(int i=0;i<(int)t.size();i++)ids.push_back({0,i});for(int i=0;i<(int)u.size();i++)ids.push_back({1,i});ids.push_back({2,0});ids.push_back({2,1});R r(ids.size());for(int i=0;i<(int)r.size();i++)for(int j=i+1;j<(int)r.size();j++){auto [a,x]=ids[i];auto[b,y]=ids[j];bool ij=a==b?(a==0?t[x]>>y&1:a==1?u[x]>>y&1:x<y):((b-a+3)%3==1);r[ij?i:j]|=1<<(ij?j:i);}return r;}
ll walk(R const&r){int n=r.size(),N=1<<n;__int128 ans=0;vector<__int128>a(n),b(n);for(int S=1;S<N;S++){fill(a.begin(),a.end(),0);for(int i=0;i<n;i++)if(S>>i&1)a[i]=1;for(int step=1;step<n;step++){fill(b.begin(),b.end(),0);for(int i=0;i<n;i++)if(a[i])for(int z=r[i]&S;z;z&=z-1){int k=__builtin_ctz((unsigned)z);b[k]+=a[i];}a.swap(b);}__int128 x=accumulate(a.begin(),a.end(),(__int128)0);ans+=((n-__builtin_popcount((unsigned)S))&1)?-x:x;}need(ans>0&&ans<(1LL<<60),"walk inclusion exclusion range");return(ll)ans;}
ll K[3][3]={{5,6,0},{6,28,24},{0,24,72}};ll form(V v,V w){ll s=0;for(int i=0;i<3;i++)for(int j=0;j<3;j++)s+=v[i]*K[i][j]*w[j];return s;}ll power(ll a,int n){ll b=1;while(n--)b*=a;return b;}ll phi(int n){return 2*power(9,n)-8*power(6,n)+13*power(4,n)+4*power(3,n)-22*power(2,n)+15;}
void structure(R const&r){int n=r.size(),F=(1<<n)-1;for(int i=0;i<n;i++){need(!(r[i]>>i&1),"no loop");for(int j=i+1;j<n;j++)need((r[i]>>j&1)+(r[j]>>i&1)==1,"tournament");int reach=1<<i;while(true){int old=reach;for(int j=0;j<n;j++)if(reach>>j&1)reach|=r[j];if(old==reach)break;}need(reach==F,"strong graph");}}
int main(){ll got[3][3]{};int colorwords=0;for(int i=1;i<=3;i++)for(int j=1;j<=3;j++)for(int k=1;k<=2;k++){vector<int>w;w.insert(w.end(),i,0);w.insert(w.end(),j,1);w.insert(w.end(),k,2);int count=0;do{bool ok=true;for(int z=1;z<(int)w.size();z++)if((w[z]-w[z-1]+3)%3!=1){ok=false;break;}if(ok)count++;colorwords++;}while(next_permutation(w.begin(),w.end()));got[i-1][j-1]+=factorial(i)*factorial(j)*factorial(k)*count;}for(int i=0;i<3;i++)for(int j=0;j<3;j++)need(got[i][j]==K[i][j],"literal all color words");ll L[3][3]={{6,0,0},{-6,3,0},{3,-3,1}},M[3][3]={{15,-11,2},{-11,13,-4},{2,-4,2}};for(int i=0;i<3;i++)for(int j=0;j<3;j++){ll x=0;for(int a=0;a<3;a++)for(int b=0;b<3;b++)x+=L[a][i]*K[a][b]*L[b][j];need(x==36*M[i][j],"exact coordinate matrix identity");}
vector<R>small;set<ll>paired;long profiles=0,pairs=0;for(int n=1;n<=5;n++)for(int code=0;code<(1<<(n*(n-1)/2));code++){R r=tournament(n,code);V v=cover(r);ll h=v[0],b=2*(v[0]+v[1]),c=3*v[0]+6*v[1]+6*v[2],f=form(v,v);need((-4*c+13*b-11*h)%2!=0,"binary coefficient odd");need(f>=phi(n)&&(f==phi(n))==(h==1),"sharp order bound equality");need(f%8==5&&f%3==(n%2?((3-h%3)* (h%3))%3:0),"paired congruences");need(form(v,V{1,0,0})>=3*power(2,n)-1,"unpaired input bound");if(n<=3)small.push_back(r);profiles++;}
for(auto const&t:small)for(auto const&u:small){R r=cyclic(t,u);ll h=walk(r);need(h==form(cover(t),cover(u)),"independent physical kernel");pairs++;}for(auto const&t:small){ll h=walk(cyclic(t,converse(t)));paired.insert(h);}need(paired==set<ll>{5,45,509,621},"actual paired small range");need(walk(cyclic(trans(4),trans(4)))==6069&&phi(4)>2000,"complete target order cutoff");for(int target=1;target<=2000;target++)need((paired.count(target)>0)==(target==5||target==45||target==509||target==621),"exact inverse membership");
ll s[4]={1,0,0,0};for(int n=1;n<=12;n++){for(int j=3;j>=1;j--)s[j]=j*s[j]+s[j-1];s[0]=0;need(form(V{s[1],s[2],s[3]},V{s[1],s[2],s[3]})==phi(n),"Stirling sharp polynomial");if(n>1)need(phi(n)>phi(n-1),"threshold control");}
R t{78,124,120,112,97,65,0};V v=cover(t);need(v==V{23,273,611},"literal witness covers");R r=cyclic(t,converse(t));structure(r);vector<int>tau;for(int i=0;i<7;i++)tau.push_back(i+7);for(int i=0;i<7;i++)tau.push_back(i);tau.push_back(15);tau.push_back(14);for(int i=0;i<16;i++){need(tau[tau[i]]==i&&tau[i]!=i,"anti involution");for(int j=0;j<16;j++)need((r[i]>>j&1)==(r[tau[j]]>>tau[i]&1),"literal anti arc");}ll h=walk(r);need(h==37050461&&form(v,v)==h,"independent sixteen vertex count");int p=5292923,bound=2300;need(h==7LL*p&&1LL*bound*bound<=p&&p<1LL*(bound+1)*(bound+1),"factor square bound");vector<bool>prime(bound+1,true);prime[0]=prime[1]=false;for(int q=2;q*q<=bound;q++)if(prime[q])for(int z=q*q;z<=bound;z+=q)prime[z]=false;int divisors=0;for(int q=2;q<=bound;q++)if(prime[q]){need(p%q,"prime trial division");divisors++;}
cout<<"{\"status\":\"PASS\",\"literal_color_words\":"<<colorwords<<",\"literal_cover_profiles\":"<<profiles<<",\"small_walk_pairs\":"<<pairs<<",\"complete_inverse_targets\":2000,\"witness_H\":"<<h<<",\"prime_divisors_tested\":"<<divisors<<",\"witness_rows\":[";for(int i=0;i<16;i++){if(i)cout<<',';cout<<r[i];}cout<<"]}\n";}
